#!/usr/bin/env python3
"""Прогон с подменой идёт по ИСХОДНОМУ тексту, а не по старому байткоду.

Python признаёт кэш устаревшим по паре «размер + время последней правки с
точностью до секунды». Подмена ТОГО ЖЕ РАЗМЕРА, внесённая в ту же секунду,
для инвалидации неотличима от отсутствия правки: прогон идёт по прежнему
`.pyc`, тесты закономерно зеленеют — и поломка объявляется ВЫЖИВШЕЙ, ни разу
не исполнившись.

Цена этого выше, чем у нашей собственной планки: планка меряет нас, а этот
инструмент едет людям. Человек читает «твои тесты не ловят вот эту подмену»
там, где подмены в прогоне не было вовсе, — ложное обвинение чужим тестам.
Зеркало того, что уже чинили в этом файле: там несостоявшийся прогон числился
ПОЙМАННОЙ поломкой, здесь исполнившийся не тот код числится ВЫЖИВШЕЙ. Врут оба.

Поясов против этого два, и они ловят разное. Здесь у каждого свой тест:
снос кэша — на подмену, под которую уже подложен чужой `.pyc`; запрет записи —
на то, что после нас в дереве человека кэша не остаётся вовсе.

Обратный контроль стоит здесь столько же, сколько прямой: починка «объявить
пойманным вообще всё» прошла бы этот файл незамеченной, поэтому настоящая
выжившая поломка проверяется отдельно и обязана остаться выжившей.

Тест самодостаточен: только стандартная библиотека и сам инструмент.
"""
from __future__ import annotations

import importlib.util
import os
import shlex
import subprocess
import sys
import tempfile
import unittest
from pathlib import Path

РЕПО = Path(__file__).resolve().parents[2]

_спек = importlib.util.spec_from_file_location(
    "ss_prove_tests_bytecode",
    РЕПО / "plugins" / "superstack" / "tools" / "prove_tests.py")
pt = importlib.util.module_from_spec(_спек)
_спек.loader.exec_module(pt)

#: Зависимость проекта — единственный файл, который проверка ИМПОРТИРУЕТ, а
#: значит единственный, для которого вообще заводится кэш байткода. Обе
#: подмены в нём — ровно той же длины, что и заменяемое: короче разницу в
#: паре «размер + время» не спрятать.
ЗАВИСИМОСТЬ = "ЗНАЧЕНИЕ = 1\nЛИШНЕЕ = 1\n"
#: Файл, которого не читает ни одна проверка. Подмена в нём обязана ВЫЖИТЬ.
ЛИШНИЙ = "ПОСТОРОННЕЕ = 1\n"
#: Вся «проверка» проекта: падает ненулевым кодом, если значение не то.
#: Зависимость именно ИМПОРТИРУЕТСЯ — иначе кэша не возникает и проверять
#: нечего.
ПРОВЕРКА = "import dep\n\nassert dep.ЗНАЧЕНИЕ == 1\n"
#: Команда тестов, которая поднимает СВОЙ интерпретатор со СВОИМ окружением.
#: Так устроены обёртки настоящих проектов, и на них запрет записи байткода
#: не распространяется: переменная до такого процесса не доезжает. Отсюда и
#: нужда во втором поясе — сносе кэша.
ОБЁРТКА = ("import os\nimport subprocess\nimport sys\n\n"
           "окружение = {k: v for k, v in os.environ.items()\n"
           "             if k != 'PYTHONDONTWRITEBYTECODE'}\n"
           "sys.exit(subprocess.run([sys.executable, 'check.py'],\n"
           "                        env=окружение).returncode)\n")

ЛОВИТСЯ = {"id": "проба.значение", "file": "dep.py",
           "find": "ЗНАЧЕНИЕ = 1", "replace": "ЗНАЧЕНИЕ = 2",
           "why": "подмена, которую проверка обязана поймать"}
ЛИШНЕЕ_В_ЗАВИСИМОСТИ = {"id": "проба.лишнее-рядом", "file": "dep.py",
                        "find": "ЛИШНЕЕ = 1", "replace": "ЛИШНЕЕ = 9",
                        "why": "подмена в том же файле, но в строке, которую "
                               "не читает ни одна проверка"}
ВЫЖИВАЕТ = {"id": "проба.посторонняя", "file": "unused.py",
            "find": "ПОСТОРОННЕЕ = 1", "replace": "ПОСТОРОННЕЕ = 2",
            "why": "подмена в файле, который не читает ни одна проверка"}

#: Настройки среды, которые молча обессмысливают весь этот файл: одна
#: запрещает писать байткод, вторая уносит его из дерева проекта. При любой из
#: них кэша рядом с исходником не возникает — и тогда проверки зеленеют
#: независимо от того, цел механизм или выпотрошен: тест доказывает не свойство
#: кода, а окружение, в котором его запустили. Планка гоняет набор именно с
#: первой из них, поэтому обе снимаются явно и на всё время проверки.
СНЯТЬ = ("PYTHONDONTWRITEBYTECODE", "PYTHONPYCACHEPREFIX")

#: Отметка времени, одна на все версии файла. Так воспроизводится та самая
#: секунда, в которую укладываются и подмена, и восстановление.
СЕКУНДА = 1_700_000_000


class Проект(unittest.TestCase):
    """Дерево, где верный исход каждой подмены известен заранее."""

    def setUp(self):
        self.среда_кладёт_кэш_рядом_с_исходником()
        врем = tempfile.TemporaryDirectory()
        self.addCleanup(врем.cleanup)
        self.корень = Path(врем.name)
        (self.корень / "dep.py").write_text(ЗАВИСИМОСТЬ, encoding="utf-8")
        (self.корень / "unused.py").write_text(ЛИШНИЙ, encoding="utf-8")
        (self.корень / "check.py").write_text(ПРОВЕРКА, encoding="utf-8")
        (self.корень / "runner.py").write_text(ОБЁРТКА, encoding="utf-8")

    def набор(self, *поломки, cmd: str = None) -> dict:
        return {"test_cmd": self.команда() if cmd is None else cmd,
                "mutations": list(поломки)}

    def команда(self, файл: str = "check.py") -> str:
        return f"{shlex.quote(sys.executable)} {файл}"

    def кэш(self) -> list:
        return sorted(str(d.relative_to(self.корень))
                      for d in self.корень.rglob("__pycache__"))

    def среда_кладёт_кэш_рядом_с_исходником(self) -> None:
        """Снять настройки кэша с окружения теста — см. `СНЯТЬ`.

        Снимаются у ВСЕХ проверок файла, а не у одной: наследуются они и
        прогревом, и прогонами самого инструмента, и любая из них превращает
        весь файл в проверку окружения.
        """
        for имя in СНЯТЬ:
            было = os.environ.pop(имя, None)
            if было is not None:
                self.addCleanup(os.environ.__setitem__, имя, было)

    def прогреть_кэш(self, cmd: str = None) -> None:
        """Прогон, наполняющий кэш, — то, что в проекте человека уже случилось.

        Кэш кладёт туда не наш инструмент, а сам проект: прошлые прогоны,
        сборка, редактор. Поэтому он и подкладывается ДО первого обращения
        к инструменту, а не выпрашивается у него.
        """
        os.utime(self.корень / "dep.py", (СЕКУНДА, СЕКУНДА))
        subprocess.run(shlex.split(cmd or self.команда()),
                       cwd=str(self.корень), capture_output=True, timeout=60)
        self.assertNotEqual(self.кэш(), [],
                            "прогрев не наполнил кэш — проверять нечего")

    def одна_секунда(self) -> None:
        """Все правки файла укладываются в ОДНУ секунду — явно, а не наудачу.

        Отметка времени выставляется перед каждым прогоном: и подмена, и
        восстановление становятся для инвалидации неотличимы от исходного
        файла — ровно то, что происходит само, когда правки попадают в одну
        секунду. Ждать этого от планировщика значило бы получить тест,
        который краснеет через раз.
        """
        настоящий = pt.run_tests

        def прогон(корень, cmd):
            os.utime(корень / "dep.py", (СЕКУНДА, СЕКУНДА))
            return настоящий(корень, cmd)

        pt.run_tests = прогон
        self.addCleanup(setattr, pt, "run_tests", настоящий)


class СтарыйБайткодНеДелаетПоломкуВыжившей(Проект):
    """Первый пояс: кэш сносится перед КАЖДЫМ прогоном с подменой."""

    def test_подмена_того_же_размера_в_ту_же_секунду_поймана(self):
        """Ложная «выжила»: прогон шёл по прежнему .pyc, подмены в нём не было."""
        self.прогреть_кэш()
        self.одна_секунда()
        v = pt.run(self.корень, self.набор(ЛОВИТСЯ))
        self.assertEqual(v["survived"], [], v)
        self.assertEqual((v["caught"], v["executed"]), (1, 1), v)
        self.assertEqual(v["status"], "pass", v)

    def test_кэш_от_предыдущей_подмены_не_доживает_до_следующей(self):
        """Перед КАЖДЫМ прогоном, а не один раз на запуск инструмента.

        Команда тестов здесь поднимает свой интерпретатор со своим окружением
        и потому кэш пишет — как любая настоящая обёртка. Кэш от первой
        подмены остаётся рядом с исходником, совпадает с восстановленным
        файлом по паре «размер + время» — и вторая подмена, снеси мы кэш
        только на старте, измерялась бы по чужому байткоду.
        """
        self.одна_секунда()
        v = pt.run(self.корень, self.набор(ЛИШНЕЕ_В_ЗАВИСИМОСТИ, ЛОВИТСЯ,
                                           cmd=self.команда("runner.py")))
        self.assertEqual([s["id"] for s in v["survived"]],
                         ["проба.лишнее-рядом"], v)
        self.assertEqual((v["caught"], v["executed"]), (1, 2), v)
        self.assertEqual(v["inconclusive"], [], v)

    def test_настоящая_выжившая_остаётся_выжившей(self):
        """Обратный контроль: «объявить пойманным всё» прошло бы файл насквозь."""
        self.прогреть_кэш()
        self.одна_секунда()
        v = pt.run(self.корень, self.набор(ВЫЖИВАЕТ))
        self.assertEqual([s["id"] for s in v["survived"]],
                         ["проба.посторонняя"], v)
        self.assertEqual(v["caught"], 0, v)
        self.assertEqual(v["status"], "fail", v)


class ПрогонНеОставляетБайткодаПослеСебя(Проект):
    """Второй пояс: то, чего не записали, не устареет и не отравит следующее."""

    def test_после_измерения_в_дереве_проекта_нет_кэша(self):
        self.одна_секунда()
        v = pt.run(self.корень, self.набор(ЛОВИТСЯ))
        # Сначала — что прогон вообще состоялся: пустое дерево после
        # несостоявшегося запуска доказывало бы не запрет записи, а его отсутствие.
        self.assertEqual(v["status"], "pass", v)
        self.assertEqual(self.кэш(), [],
                         "после измерения в чужом дереве остался наш кэш")


class СносКэшаНеТрогаетНичегоКромеКэша(Проект):
    """Дерево чужое: удалять здесь можно ровно то, что восстановимо само."""

    def test_снесены_только_каталоги_кэша(self):
        (self.корень / "sub").mkdir()
        (self.корень / "sub" / "__pycache__").mkdir()
        (self.корень / "sub" / "__pycache__" / "dep.pyc").write_bytes(b"stale")
        (self.корень / "sub" / "важное.txt").write_text("не трогать",
                                                        encoding="utf-8")
        снесено = pt.purge_bytecode(self.корень)
        self.assertEqual(снесено, 1)
        self.assertFalse((self.корень / "sub" / "__pycache__").exists())
        self.assertEqual((self.корень / "sub" / "важное.txt").read_text("utf-8"),
                         "не трогать")
        self.assertEqual((self.корень / "dep.py").read_text("utf-8"), ЗАВИСИМОСТЬ)


if __name__ == "__main__":
    unittest.main()
